import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { Link, Route, Router as WouterRouter, Switch, useLocation } from 'wouter';
import { Activity, AlertTriangle, ArrowDownRight, ArrowRight, BarChart3, CalendarDays, Check, CheckCircle2, ClipboardList, Clock3, Download, FileJson2, FileSpreadsheet, Filter, LayoutDashboard, LockKeyhole, Menu, PackageCheck, Pencil, Plus, Search, ShieldAlert, Trash2, Truck, Upload, Waves, X } from 'lucide-react';
import { BarController, BarElement, CategoryScale, Chart as ChartJS, Filler, Legend, LineController, LinearScale, LineElement, PointElement, Tooltip, type ChartConfiguration, type ChartData, type ChartOptions } from 'chart.js';

ChartJS.register(BarController, CategoryScale, LineController, LinearScale, PointElement, LineElement, BarElement, Filler, Tooltip, Legend);

type Plan = {
 id:string; sn:number; date:string; project:string; location:string; grade:string; so:string; volume:number; pumpCar:string; trucks:number;
 pumpAtSite:string; start:string; finish:string; finishNextDay:boolean; requested:string; dispatch:string; returned:string;
 icePerM3:number; totalIce:number; mix:string; sap:string; po:string; labHelper:string;
};
type Status='Completed'|'Partial'|'Cancelled'|'Pending';
type Actual = {id:string; planId:string; volume:number; grade:string; trucks:number; requested:string; pumpAtSite:string; dispatch:string; returned:string; status:Status; reason:string; remarks:string};
type Dataset={plans:Plan[]; actuals:Actual[]};
const STORAGE='peliyagoda-ops-v1';
const AUTH='peliyagoda-ops-session';
const REASONS=['Plant Loading Delay','Batching Delay','Truck Availability','Pump Availability','Site Waiting','Site Unloading Delay','Traffic','Weather','Equipment Issue','Material Issue','Communication Issue','Other'];
const blankPlan=():Omit<Plan,'id'|'sn'>=>({date:new Date().toISOString().slice(0,10),project:'',location:'',grade:'',so:'',volume:0,pumpCar:'',trucks:0,pumpAtSite:'',start:'08:00',finish:'11:30',finishNextDay:false,requested:'',dispatch:'',returned:'',icePerM3:0,totalIce:0,mix:'',sap:'',po:'',labHelper:''});
const seedPlans:Plan[]=[
 {id:'seed-1',sn:1,date:'2025-03-18',project:'Colombo City Project',location:'Union Place, Colombo 02',grade:'Grade 35',so:'SO-24871',volume:80,pumpCar:'PC-04',trucks:6,pumpAtSite:'07:45',start:'08:00',finish:'11:30',finishNextDay:false,requested:'07:30',dispatch:'08:00',returned:'11:30',icePerM3:18,totalIce:1440,mix:'Sika ViscoCrete 3010',sap:'BOM-35-COL',po:'PO-CCP-1024',labHelper:'N. Perera'},
 {id:'seed-2',sn:2,date:'2025-03-18',project:'Port City – Marina',location:'Port City, Colombo',grade:'Grade 40',so:'SO-24876',volume:62, pumpCar:'PC-02',trucks:5,pumpAtSite:'08:10',start:'08:30',finish:'11:15',finishNextDay:false,requested:'08:00',dispatch:'08:20',returned:'11:20',icePerM3:16,totalIce:992,mix:'MasterGlenium SKY 8233',sap:'BOM-40-PC',po:'PO-PC-771',labHelper:'S. Jayasinghe'},
 {id:'seed-3',sn:3,date:'2025-03-18',project:'Kaduwela Interchange',location:'Kothalawala, Kaduwela',grade:'Grade 30',so:'SO-24882',volume:48,pumpCar:'PC-07',trucks:4,pumpAtSite:'09:00',start:'09:15',finish:'11:45',finishNextDay:false,requested:'08:45',dispatch:'09:10',returned:'11:40',icePerM3:20,totalIce:960,mix:'Sika ViscoCrete 1010',sap:'BOM-30-KI',po:'PO-KI-405',labHelper:'M. Fernando'},
 {id:'seed-4',sn:4,date:'2025-03-17',project:'Colombo City Project',location:'Union Place, Colombo 02',grade:'Grade 35',so:'SO-24832',volume:72,pumpCar:'PC-04',trucks:6,pumpAtSite:'07:30',start:'08:00',finish:'11:00',finishNextDay:false,requested:'07:30',dispatch:'08:08',returned:'11:10',icePerM3:18,totalIce:1296,mix:'Sika ViscoCrete 3010',sap:'BOM-35-COL',po:'PO-CCP-1022',labHelper:'N. Perera'},
 {id:'seed-5',sn:5,date:'2025-03-17',project:'Rajagiriya Tower',location:'Nawala Road, Rajagiriya',grade:'Grade 40',so:'SO-24839',volume:54,pumpCar:'PC-01',trucks:5,pumpAtSite:'10:00',start:'10:15',finish:'13:00',finishNextDay:false,requested:'09:45',dispatch:'10:13',returned:'13:27',icePerM3:15,totalIce:810,mix:'MasterGlenium ACE 430',sap:'BOM-40-RT',po:'PO-RT-229',labHelper:'K. Silva'},
 {id:'seed-6',sn:6,date:'2025-03-16',project:'Peliyagoda Warehouse',location:'Wattala Road, Peliyagoda',grade:'Grade 25',so:'SO-24798',volume:45,pumpCar:'PC-03',trucks:4,pumpAtSite:'06:45',start:'07:00',finish:'09:45',finishNextDay:false,requested:'06:30',dispatch:'07:02',returned:'09:43',icePerM3:17,totalIce:765,mix:'Sika ViscoCrete 1010',sap:'BOM-25-PW',po:'PO-PW-118',labHelper:'D. Gunaratne'},
];
const seedActuals:Actual[]=[
 {id:'act-1',planId:'seed-1',volume:76,grade:'Grade 35',trucks:7,requested:'07:30',pumpAtSite:'07:55',dispatch:'08:22',returned:'11:48',status:'Completed',reason:'Truck Availability',remarks:'One truck joined late; remaining delivery completed.'},
 {id:'act-2',planId:'seed-2',volume:62,grade:'Grade 40',trucks:5,requested:'08:00',pumpAtSite:'08:12',dispatch:'08:32',returned:'11:28',status:'Completed',reason:'Plant Loading Delay',remarks:'Short loading queue at dispatch.'},
 {id:'act-3',planId:'seed-3',volume:43,grade:'Grade 30',trucks:4,requested:'08:45',pumpAtSite:'09:04',dispatch:'09:34',returned:'12:03',status:'Partial',reason:'Site Waiting',remarks:'Site access released later than agreed.'},
 {id:'act-4',planId:'seed-4',volume:72,grade:'Grade 35',trucks:6,requested:'07:30',pumpAtSite:'07:33',dispatch:'08:08',returned:'11:10',status:'Completed',reason:'Plant Loading Delay',remarks:''},
 {id:'act-5',planId:'seed-5',volume:54,grade:'Grade 40',trucks:5,requested:'09:45',pumpAtSite:'10:01',dispatch:'10:43',returned:'13:27',status:'Completed',reason:'Batching Delay',remarks:'Batching sequence adjustment.'},
 {id:'act-6',planId:'seed-6',volume:45,grade:'Grade 25',trucks:4,requested:'06:30',pumpAtSite:'06:51',dispatch:'07:02',returned:'09:43',status:'Completed',reason:'On Time',remarks:''},
];
const seedData:Dataset={plans:seedPlans.map((p,i)=>{const d=new Date();d.setDate(d.getDate()-(i<3?0:i<5?1:2));return{...p,date:d.toISOString().slice(0,10)};}),actuals:seedActuals};
const emptyData:Dataset={plans:[],actuals:[]};
const mins=(time:string)=>{if(!time)return null;const [h,m]=time.split(':').map(Number);return h*60+m};
const delay=(actual:string,planned:string,extra=0)=>{const a=mins(actual),p=mins(planned);if(a===null||p===null)return null;let d=a+extra-p;if(d < -720)d+=1440;if(d>720)d-=1440;return d};
const band=(n:number|null)=>n===null?'pending':n<=0?'on-time':n<=15?'minor':n<=30?'moderate':'major';
const bandText=(n:number|null)=>({pending:'No actual', 'on-time':'On time',minor:'Minor',moderate:'Moderate',major:'Major'} as Record<string,string>)[band(n)];
const num=(x:number|null|undefined,digits=0)=>x==null?'—':Number(x).toLocaleString('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const fmtTime=(x:string)=>x||'—';
const today=()=>new Date().toISOString().slice(0,10);
function loadData():Dataset{try{const s=localStorage.getItem(STORAGE);if(!s){localStorage.setItem(STORAGE,JSON.stringify(seedData));return seedData;}const d=JSON.parse(s);return{plans:Array.isArray(d.plans)?d.plans:[],actuals:Array.isArray(d.actuals)?d.actuals:[]};}catch{return seedData;}}
function uid(){return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;}

function OperationsApp(){
 const [data,setData]=useState<Dataset>(loadData);const [authed,setAuthed]=useState(()=>localStorage.getItem(AUTH)==='yes');const [path,setPath]=useLocation();const [toast,setToast]=useState('');const [mobileOpen,setMobileOpen]=useState(false);
 useEffect(()=>{localStorage.setItem(STORAGE,JSON.stringify(data));},[data]);
  useEffect(()=>{if(!toast)return undefined;const t=setTimeout(()=>setToast(''),2600);return()=>clearTimeout(t);},[toast]);
 const persist=(d:Dataset,msg='Saved to this browser')=>{setData(d);setToast(msg);};
 const login=()=>{localStorage.setItem(AUTH,'yes');setAuthed(true);setPath('/dashboard');};
 const logout=()=>{localStorage.removeItem(AUTH);setAuthed(false);setPath('/');};
 const actualFor=(id:string)=>data.actuals.find(a=>a.planId===id);
 const updatePlan=(p:Plan)=>persist({...data,plans:data.plans.map(x=>x.id===p.id?p:x)},'Daily plan saved');
 const removePlan=(id:string)=>{persist({plans:data.plans.filter(x=>x.id!==id),actuals:data.actuals.filter(x=>x.planId!==id)},'Plan and linked actual removed');};
 const saveActual=(a:Actual)=>persist({...data,actuals:[...data.actuals.filter(x=>x.planId!==a.planId),a]},'Operation actual saved');
 if(!authed)return <Welcome onLogin={login}/>;
 const title=({dashboard:'Operations overview',plan:'Daily production plan',actual:'Delivery actuals',comparison:'Plan vs actual',delays:'Delay intelligence',records:'Operations records'} as Record<string,string>)[path.replace('/','')]||'Operations overview';
 return <div className="app-shell">
  <div className={`mobile-overlay ${mobileOpen?'show':''}`} onClick={()=>setMobileOpen(false)} />
  <aside className={`sidebar ${mobileOpen?'open':''}`}>
   <div className="brand"><div className="brand-mark">A</div><div><div className="brand-title">ACCESS ENGINEERING</div><div className="brand-sub">Peliyagoda concrete plant</div></div></div>
   <div className="nav-label">Operations</div><nav className="nav-list">
    <NavItem href="/dashboard" icon={<LayoutDashboard size={17}/>} text="Overview" active={path==='/dashboard'} close={()=>setMobileOpen(false)}/>
    <NavItem href="/plan" icon={<CalendarDays size={17}/>} text="Daily plan" active={path==='/plan'} close={()=>setMobileOpen(false)}/>
    <NavItem href="/actual" icon={<Truck size={17}/>} text="Delivery actuals" active={path==='/actual'} close={()=>setMobileOpen(false)}/>
    <NavItem href="/comparison" icon={<BarChart3 size={17}/>} text="Plan vs actual" active={path==='/comparison'} close={()=>setMobileOpen(false)}/>
    <NavItem href="/delays" icon={<Clock3 size={17}/>} text="Delay intelligence" active={path==='/delays'} close={()=>setMobileOpen(false)}/>
    <NavItem href="/records" icon={<ClipboardList size={17}/>} text="All records" active={path==='/records'} close={()=>setMobileOpen(false)}/>
   </nav>
  <div className="sidebar-foot"><strong></strong><br/><button className="button small" style={{marginTop:10,background:'transparent',borderColor:'#ffffff30',color:'#d5e3ef'}} onClick={logout} data-testid="button-sign-out"><LockKeyhole size={12}/> Sign out</button></div>
  </aside>
  <main className="main-area">
   <header className="topbar"><div className="top-left"><button className="menu-toggle" aria-label="Open navigation" onClick={()=>setMobileOpen(!mobileOpen)} data-testid="button-menu"><Menu size={20}/></button><span className="crumb">Plant operations&nbsp; / &nbsp;</span><span className="topbar-title">{title}</span></div><div className="top-meta"><span className="plant-chip"></span><span>{new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</span><span style={{width:27,height:27,borderRadius:'50%',background:'#e3f3f7',color:'#176b7c',display:'grid',placeItems:'center',fontWeight:700}}>AE</span></div></header>
   <Switch>
    <Route path="/dashboard"><Dashboard data={data} actualFor={actualFor} onNavigate={setPath}/></Route>
    <Route path="/plan"><PlanPage data={data} actualFor={actualFor} updatePlan={updatePlan} createPlan={p=>persist({...data,plans:[{...p,id:uid(),sn:Math.max(0,...data.plans.map(x=>x.sn))+1},...data.plans]},'Daily plan created')} duplicate={p=>persist({...data,plans:[{...p,id:uid(),sn:Math.max(0,...data.plans.map(x=>x.sn))+1,date:today(),so:p.so+'-COPY'},...data.plans]},'Plan duplicated')} remove={removePlan}/></Route>
    <Route path="/actual"><ActualPage data={data} actualFor={actualFor} save={saveActual}/></Route>
    <Route path="/comparison"><Comparison data={data} actualFor={actualFor}/></Route>
    <Route path="/delays"><DelaysPage data={data} actualFor={actualFor}/></Route>
     <Route path="/records"><RecordsPage data={data} actualFor={actualFor} updatePlan={updatePlan} removePlan={removePlan} saveNow={()=>{localStorage.setItem(STORAGE,JSON.stringify(data));setToast('Data saved in this browser');}} clear={()=>{if(window.confirm('Clear all saved plans and actuals from this browser? This cannot be undone.'))persist(emptyData,'All local records cleared');}}/></Route>
    <Route><Dashboard data={data} actualFor={actualFor} onNavigate={setPath}/></Route>
   </Switch>
  </main>{toast&&<div className="toast-msg" role="status">{toast}</div>}
 </div>;
}

function NavItem({href,icon,text,active,close}:{href:string;icon:ReactNode;text:string;active:boolean;close:()=>void}){
 return <Link href={href} className={`nav-link ${active?'active':''}`} onClick={close} data-testid={`link-${text.toLowerCase().replaceAll(' ','-')}`}>{icon}<span>{text}</span></Link>;
}
function Welcome({onLogin}:{onLogin:()=>void}){
 const [pass,setPass]=useState('');const [error,setError]=useState('');const submit=(e:FormEvent)=>{e.preventDefault();if(pass==='Access@paliyagoda'){onLogin();}else setError('Password did not match. Try the workspace access password.');};
 return <div className="welcome-screen"><section className="welcome-copy"><div className="welcome-brand"><div className="brand-mark">A</div><div><div className="brand-title">ACCESS ENGINEERING</div><div className="brand-sub">Plant performance · Peliyagoda</div></div></div><div className="welcome-kicker">Operations control room</div><h1>Concrete delivery,<br/>in clear view<span className="wave-mark"><Waves size={29}/></span></h1><p>Welcome — your production performance at a glance — track delays, identify issues, improve efficiency.</p><div className="welcome-foot">PELIYAGODA CONCRETE PLANT &nbsp;·&nbsp; OPERATIONS CONTROL</div></section><section className="welcome-access"><form className="access-card" onSubmit={submit}><div className="eyebrow">Workspace access</div><h2>Welcome back</h2><p>Enter the workspace password to open the Peliyagoda operations workspace.</p><label className="field-label" htmlFor="workspace-password">Workspace password</label><input id="workspace-password" className="field" type="password" autoComplete="current-password" value={pass} onChange={e=>{setPass(e.target.value);setError('');}} placeholder="Enter password" data-testid="input-password"/>{error&&<div className="error-msg" role="alert">{error}</div>}<button type="submit" className="button primary" data-testid="button-access">Open operations workspace <ArrowRight size={15}/></button><div className="access-note"><ShieldAlert size={16}/><span><strong>Local access gate.</strong> This browser-based access screen is not secure production authentication. Records stay in this browser.</span></div></form></section></div>;
}
function PageHeader({eyebrow,title,subtitle,children}:{eyebrow:string;title:string;subtitle:string;children?:ReactNode}){return <div className="page-heading animate-in"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{children&&<div className="actions">{children}</div>}</div>}
function Panel({title,subtitle,children,action}:{title:string;subtitle?:string;children:ReactNode;action?:ReactNode}){return <section className="panel"><div className="panel-head"><div><div className="panel-title">{title}</div>{subtitle&&<div className="panel-sub">{subtitle}</div>}</div>{action}</div>{children}</section>}
type ChartKind='bar'|'line';
function makeChartRef(type:ChartKind,data:ChartData<ChartKind,(number|null)[]>,options:ChartOptions<ChartKind>){
  let chart:ChartJS|undefined;
  return(canvas:HTMLCanvasElement|null)=>{chart?.destroy();chart=undefined;if(canvas)chart=new ChartJS(canvas,{type,data,options} as ChartConfiguration<ChartKind,(number|null)[]>);};
}
function Kpi({label,value,foot,icon,accent}:{label:string;value:string;foot:string;icon:ReactNode;accent?:boolean}){return <div className="kpi" data-testid={`kpi-${label.toLowerCase().replaceAll(' ','-')}`}><div className="kpi-top"><span>{label}</span><span className="kpi-icon">{icon}</span></div><div className="kpi-value" style={accent?{color:'#b44b4f'}:{}}>{value}</div><div className="kpi-foot">{foot}</div></div>}
function rowData(data:Dataset,actualFor:(id:string)=>Actual|undefined){return data.plans.map(p=>{const a=actualFor(p.id);const start=a?delay(a.dispatch,p.start):null;const finish=a?delay(a.returned,p.finish,p.finishNextDay?1440:0):null;const lead=start??0;return{p,a,start,finish,lead,volumeDelta:a?a.volume-p.volume:null,truckDelta:a?a.trucks-p.trucks:null,delayTotal:a?Math.max(0,start||0)+Math.max(0,finish||0):0,band:band(start)}});}
function Dashboard({data,actualFor,onNavigate}:{data:Dataset;actualFor:(id:string)=>Actual|undefined;onNavigate:(p:string)=>void}){
  const [range,setRange]=useState('7');const rows=rowData(data,actualFor);const actualRows=rows.filter(x=>x.a);const completed=actualRows.filter(x=>x.a?.status==='Completed').length;const delayedRows=actualRows.filter(x=>x.delayTotal>0);const delayed=delayedRows.length;const onTime=actualRows.length?Math.round((actualRows.filter(x=>(x.start||0)<=0&&(x.finish||0)<=0).length/actualRows.length)*100):0;const avg=delayedRows.length?Math.round(delayedRows.reduce((s,x)=>s+x.delayTotal,0)/delayedRows.length):0;const totalDelay=actualRows.reduce((s,x)=>s+(x.delayTotal||0),0);const planVol=data.plans.reduce((s,p)=>s+p.volume,0);const actualVol=actualRows.reduce((s,x)=>s+(x.a?.volume||0),0);
  const trend=useMemo(()=>{const actual=rows.filter(x=>x.a);let keys:string[];if(range==='all'){keys=Array.from(new Set(actual.map(x=>x.p.date))).sort();}else{const days=Number(range);keys=[];for(let i=days-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);keys.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);}}return keys.map(key=>{const items=actual.filter(x=>x.p.date===key);return{label:new Date(`${key}T12:00:00`).toLocaleDateString('en-US',{day:'numeric',month:'short'}),value:items.length?items.reduce((s,x)=>s+x.delayTotal,0)/items.length:0};});},[range,data]);
  const delayData={labels:trend.map(x=>x.label),datasets:[{label:'Average delay (minutes)',data:trend.map(x=>Number(x.value.toFixed(1))),borderColor:'#20a9c2',backgroundColor:'rgba(32,169,194,.13)',fill:true,tension:.32,pointRadius:3,pointHoverRadius:5,pointBackgroundColor:'#fff',pointBorderColor:'#20a9c2',pointBorderWidth:2}]};
  const chartOptions={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:true}},scales:{x:{grid:{display:false},ticks:{color:'#8293a1',maxTicksLimit:8}},y:{beginAtZero:true,grid:{color:'#edf1f4'},ticks:{color:'#8293a1'},title:{display:true,text:'Minutes',color:'#8293a1'}}}};
  const barOptions={...chartOptions,indexAxis:'y' as const,scales:{x:{beginAtZero:true,grid:{color:'#edf1f4'},ticks:{color:'#8293a1'}},y:{grid:{display:false},ticks:{color:'#607587',font:{size:10}}}}};
  const chartRows=rows.slice(0,6);const labels=chartRows.map(x=>x.p.project);
  const volumeData={labels,datasets:[{label:'Planned',data:chartRows.map(x=>x.p.volume),backgroundColor:'#193c5c',borderRadius:4},{label:'Actual',data:chartRows.map(x=>x.a?.volume??null),backgroundColor:'#39bbd1',borderRadius:4}]};
  const truckData={labels,datasets:[{label:'Allocated',data:chartRows.map(x=>x.p.trucks),backgroundColor:'#193c5c',borderRadius:4},{label:'Used',data:chartRows.map(x=>x.a?.trucks??null),backgroundColor:'#39bbd1',borderRadius:4}]};
 const reasons=REASONS.map(reason=>({reason,items:actualRows.filter(x=>x.a?.reason===reason),mins:actualRows.filter(x=>x.a?.reason===reason).reduce((s,x)=>s+Math.max(0,x.start||0)+Math.max(0,x.finish||0),0)})).filter(x=>x.items.length).sort((a,b)=>b.mins-a.mins).slice(0,5);
  return <div className="content"><PageHeader eyebrow="Peliyagoda plant · Daily view" title="Production at a glance" subtitle="A live read of planned output, delivery execution and time lost across the plant."><button className="button" onClick={()=>onNavigate('/records')}><ClipboardList size={14}/> View records</button><button className="button primary" onClick={()=>onNavigate('/plan')}><Plus size={15}/> New daily plan</button></PageHeader>
  <div className="kpi-grid">
   <Kpi label="Planned jobs" value={num(data.plans.length)} foot="All saved plan records" icon={<ClipboardList size={15}/>}/><Kpi label="Completed jobs" value={num(completed)} foot={`${actualRows.length} jobs with actuals`} icon={<CheckCircle2 size={15}/>}/><Kpi label="Delayed jobs" value={num(delayed)} foot="Start or finish after plan" icon={<AlertTriangle size={15}/>} accent/><Kpi label="On-time rate" value={`${onTime}%`} foot="Jobs with no positive delay" icon={<Activity size={15}/>}/>
    <Kpi label="Average delay" value={`${avg} min`} foot="Per delayed job · start + finish" icon={<Clock3 size={15}/>}/><Kpi label="Total delay" value={`${num(totalDelay)} min`} foot="Positive start + finish delay" icon={<ArrowDownRight size={15}/>} accent/><Kpi label="Planned volume" value={`${num(planVol)} m³`} foot="Across saved daily plans" icon={<PackageCheck size={15}/>}/><Kpi label="Actual volume" value={`${num(actualVol)} m³`} foot="Across operations with actuals" icon={<Truck size={15}/>}/><Kpi label="Volume variance" value={`${actualVol-planVol>0?'+':''}${num(actualVol-planVol)} m³`} foot="Actual volume minus planned volume" icon={<ArrowDownRight size={15}/>} accent={actualVol<planVol}/>
  </div>
   <div className="grid-main"><Panel title="Daily average delay" subtitle="Average positive start + finish delay by plan date" action={<div className="chart-controls">{[['7','7D'],['30','30D'],['90','90D'],['all','All']].map(([v,l])=><button className={range===v?'selected':''} key={v} onClick={()=>setRange(v)} data-testid={`button-trend-${v}`}>{l}</button>)}</div>}><div className="panel-body"><div style={{height:230}}><canvas ref={makeChartRef('line',delayData,chartOptions)} role="img" aria-label="Daily average delay in minutes"/></div></div></Panel>
  <Panel title="Delay reasons" subtitle="Occurrences and cumulative time impact" action={<button className="button small" onClick={()=>onNavigate('/delays')}>Full analysis <ArrowRight size={12}/></button>}><div className="panel-body">{reasons.length?reasons.map(x=><div className="metric-line" key={x.reason}><span>{x.reason}<small style={{display:'block',fontSize:9,color:'#98a4af',marginTop:2}}>{x.items.length} {x.items.length===1?'occurrence':'occurrences'}</small></span><strong>{x.mins} min</strong></div>):<EmptyText text="Delay insights appear when operation actuals are recorded."/>}</div></Panel></div>
   <div className="grid-equal"><Panel title="Volume · plan vs actual" subtitle="m³ by project · first 6 plans"><div className="panel-body"><div className="chart-legend" style={{marginBottom:12}}><span><i className="legend-dot" style={{background:'#193c5c'}}/>Planned</span><span><i className="legend-dot" style={{background:'#39bbd1'}}/>Actual</span></div><div style={{height:210}}><canvas ref={makeChartRef('bar',volumeData,barOptions)} role="img" aria-label="Planned and actual concrete volume by project"/></div></div></Panel>
   <Panel title="Truck deployment" subtitle="Allocated vs used across saved operations"><div className="panel-body"><div className="chart-legend" style={{marginBottom:12}}><span><i className="legend-dot" style={{background:'#193c5c'}}/>Allocated</span><span><i className="legend-dot" style={{background:'#39bbd1'}}/>Used</span></div><div style={{height:210}}><canvas ref={makeChartRef('bar',truckData,barOptions)} role="img" aria-label="Allocated and actual trucks by project"/></div></div></Panel></div>
  <Panel title="Start / finish timing" subtitle="Planned vs actual clock positions · 06:00–14:00"><div className="panel-body"><div className="chart-legend" style={{marginBottom:12}}><span><i className="legend-dot" style={{background:'#193c5c'}}/>Planned</span><span><i className="legend-dot" style={{background:'#39bbd1'}}/>Actual</span><span style={{marginLeft:'auto'}}>Earlier ← &nbsp;06:00 &nbsp;···························· 14:00 &nbsp;→ Later</span></div>{rows.slice(0,6).map(x=><div key={x.p.id} style={{display:'grid',gridTemplateColumns:'120px 1fr',gap:13,alignItems:'center',padding:'9px 0',borderTop:'1px solid #eef2f5'}}><div><div className="project-cell" style={{fontSize:11}}>{x.p.project.length>18?x.p.project.slice(0,17)+'…':x.p.project}</div><div className="secondary-cell">Start / finish</div></div><div style={{display:'grid',gap:8}}>{([{label:'Start',plan:x.p.start,actual:x.a?.dispatch},{label:'Finish',plan:x.p.finish,actual:x.a?.returned}]).map(t=>{const pos=(time:string)=>Math.max(0,Math.min(100,((mins(time)??360)-360)/480*100));return <div key={t.label} style={{display:'grid',gridTemplateColumns:'35px 1fr 86px',gap:8,alignItems:'center'}}><small style={{fontSize:9,color:'#8091a0'}}>{t.label}</small><div style={{height:8,background:'#eef2f5',borderRadius:8,position:'relative'}}><span title={`Planned ${t.plan}`} style={{position:'absolute',left:`${pos(t.plan)}%`,top:-2,width:4,height:12,background:'#193c5c',borderRadius:3}}/>{t.actual&&<span title={`Actual ${t.actual}`} style={{position:'absolute',left:`${pos(t.actual)}%`,top:-2,width:4,height:12,background:'#39bbd1',borderRadius:3}}/>}</div><span className="mono" style={{fontSize:9,color:'#65798c'}}>{t.plan} / {t.actual||'—'}</span></div>;})}</div></div>)}</div></Panel>
  <Panel title="Today on the schedule" subtitle="Plan and execution snapshot"><div className="table-wrap"><table><thead><tr><th>Project / SO</th><th>Planned</th><th>Actual</th><th>Start variance</th><th>Finish variance</th><th>Volume Δ</th><th>Status</th></tr></thead><tbody>{rows.filter(x=>x.p.date===today()).slice(0,7).map(x=><tr key={x.p.id}><td><div className="project-cell">{x.p.project}</div><div className="secondary-cell">{x.p.so} · {x.p.location}</div></td><td className="mono">{x.p.start}–{x.p.finish}</td><td className="mono">{x.a?`${x.a.dispatch}–${x.a.returned}`:'Awaiting actual'}</td><td><DelayValue value={x.start}/></td><td><DelayValue value={x.finish}/></td><td className="mono">{x.volumeDelta===null?'—':`${x.volumeDelta>0?'+':''}${x.volumeDelta} m³`}</td><td><StatusBadge status={x.a?.status||'Pending'} delayMin={x.start}/></td></tr>)}{!rows.some(x=>x.p.date===today())&&<tr><td colSpan={7}><EmptyText text="No jobs are scheduled for today yet." action={<button className="button small primary" onClick={()=>onNavigate('/plan')}><Plus size={12}/> Create today's plan</button>}/></td></tr>}</tbody></table></div></Panel>
 </div>;
}
function EmptyText({text,action}:{text:string;action?:ReactNode}){return <div className="empty-state"><ClipboardList size={24} color="#9aabb8"/><h3>Nothing to show yet</h3><p>{text}</p>{action}</div>}
function StatusBadge({status,delayMin}:{status:Status;delayMin?:number|null}){if(status==='Pending')return <span className="badge pending">Pending actual</span>;return <span className={`badge ${status.toLowerCase()}`} title={delayMin==null?undefined:`Start variance ${delayMin>0?'+':''}${delayMin} minutes`}>{status}</span>}
function DelayValue({value}:{value:number|null}){return value===null?<span className="mono" style={{color:'#9aa7b2'}}>—</span>:<span className={`badge ${band(value)}`}>{value>0?'+':''}{value} min · {bandText(value)}</span>}

const planFields:[keyof Omit<Plan,'id'|'sn'>,string,string][]=[
 ['date','Plan date','date'],['project','Customer / project','text'],['location','Delivery location','text'],['grade','Concrete grade','text'],['so','SO number','text'],['volume','Planned volume (m³)','number'],['pumpCar','Pump car number','text'],['trucks','Allocated trucks','number'],['pumpAtSite','Pump car at site','time'],['start','Planned start','time'],['finish','Planned finish','time'],['requested','Requested-by-site time','time'],['dispatch','Planned 1st-truck dispatch','time'],['returned','Planned last-truck return','time'],['icePerM3','Ice per m³ (kg)','number'],['totalIce','Total ice (kg)','number'],['mix','Mix design / admixture','text'],['sap','SAP BOM code','text'],['po','PO reference','text'],['labHelper','Lab helper name','text']
];
function PlanPage({data,actualFor,updatePlan,createPlan,duplicate,remove}:{data:Dataset;actualFor:(id:string)=>Actual|undefined;updatePlan:(p:Plan)=>void;createPlan:(p:Omit<Plan,'id'|'sn'>)=>void;duplicate:(p:Plan)=>void;remove:(id:string)=>void}){
 const [editing,setEditing]=useState<Plan|null|false>(false);const [query,setQuery]=useState('');const [date,setDate]=useState('');const [sort,setSort]=useState('date');
 const rows=[...data.plans].filter(p=>(!date||p.date===date)&&`${p.project} ${p.so} ${p.location}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='project'?a.project.localeCompare(b.project):b.date.localeCompare(a.date));
  return <div className="content"><PageHeader eyebrow="Plan entry" title="Daily production plan" subtitle="Build a clear dispatch schedule before the first truck leaves."><button className="button primary" onClick={()=>setEditing(null)} data-testid="button-new-plan"><Plus size={15}/> Create daily plan</button></PageHeader>
  <Panel title={`${rows.length} saved plans`} subtitle="Plans are stored locally on this browser"><div className="filter-bar"><div className="field" style={{display:'flex',gap:8,alignItems:'center',padding:'0 9px'}}><Search size={14} color="#8495a3"/><input className="field search-field" style={{border:0,padding:'8px 0',boxShadow:'none'}} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Project, SO number, location" data-testid="input-plan-search"/></div><input type="date" className="field" value={date} onChange={e=>setDate(e.target.value)} aria-label="Filter by plan date" data-testid="filter-plan-date"/><select className="field" value={sort} onChange={e=>setSort(e.target.value)} aria-label="Sort plans"><option value="date">Newest first</option><option value="project">Project A–Z</option></select></div><div className="table-wrap"><table><thead><tr><th>Plan date</th><th>Project / customer</th><th>Grade / SO</th><th>Volume</th><th>Truck allocation</th><th>Planned window</th><th>Execution</th><th>Actions</th></tr></thead><tbody>{rows.map(p=>{const a=actualFor(p.id);return <tr key={p.id} data-testid={`row-plan-${p.id}`}><td className="mono">{p.date}</td><td><div className="project-cell">{p.project}</div><div className="secondary-cell">{p.location}</div></td><td>{p.grade}<div className="secondary-cell">{p.so}</div></td><td className="mono">{num(p.volume)} m³</td><td className="mono">{p.trucks} trucks</td><td className="mono">{p.start} – {p.finish}{p.finishNextDay?' +1d':''}</td><td><StatusBadge status={a?.status||'Pending'} delayMin={a?delay(a.dispatch,p.start):null}/></td><td><div className="actions"><button className="button small" title="Edit plan" onClick={()=>setEditing(p)} data-testid={`button-edit-plan-${p.id}`}><Pencil size={12}/></button><button className="button small" title="Duplicate plan" onClick={()=>duplicate(p)} data-testid={`button-duplicate-plan-${p.id}`}><FileSpreadsheet size={12}/></button><button className="button small danger" title="Delete plan" onClick={()=>window.confirm(`Delete ${p.project} and its linked actual?`)&&remove(p.id)} data-testid={`button-delete-plan-${p.id}`}><Trash2 size={12}/></button></div></td></tr>})}{!rows.length&&<tr><td colSpan={8}><EmptyText text="No plans match these filters. Create a plan to begin scheduling deliveries." action={<button className="button primary small" onClick={()=>setEditing(null)}><Plus size={12}/> Create plan</button>}/></td></tr>}</tbody></table></div></Panel>
  {editing!==false&&<PlanModal initial={editing||undefined} onClose={()=>setEditing(false)} onSave={p=>{if(editing)updatePlan({...p,id:editing.id,sn:editing.sn});else createPlan(p);setEditing(false);}}/>}
 </div>;
}
function PlanModal({initial,onClose,onSave}:{initial?:Plan;onClose:()=>void;onSave:(p:Omit<Plan,'id'|'sn'>)=>void}){
 const [form,setForm]=useState<Omit<Plan,'id'|'sn'>>(initial?(({id,sn,...r})=>r)(initial):blankPlan());const [error,setError]=useState('');
 const set=(k:keyof Omit<Plan,'id'|'sn'>,v:string|number|boolean)=>setForm(f=>({...f,[k]:v}));
 const submit=(e:FormEvent)=>{e.preventDefault();if(!form.project||!form.location||!form.grade||!form.so||!form.start||!form.finish){setError('Complete customer/project, location, grade, SO number, planned start and finish.');return;}if(form.volume<=0||form.trucks<0){setError('Planned volume must be greater than zero and truck allocation cannot be negative.');return;}if(!form.finishNextDay&&mins(form.finish)!==null&&mins(form.start)!==null&&mins(form.finish)!<mins(form.start)!){setError('Finish is before start. Select the cross-midnight exception if the job finishes the next day.');return;}onSave(form);};
  return <div className="dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="dialog"><div className="dialog-header"><div><h2>{initial?'Edit daily plan':'Create daily plan'}</h2><p>Enter the dispatch plan and job references.</p></div><button className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={19}/></button></div><form className="dialog-content" onSubmit={submit}><div className="form-grid">{planFields.map(([key,label,type])=><div className={`form-field ${key==='project'||key==='location'||key==='mix'?'wide':''}`} key={key}><label className="field-label" htmlFor={`plan-${key}`}>{label}{['project','location','grade','volume','so','start','finish'].includes(key)?' *':''}</label><input className="field" id={`plan-${key}`} type={type} min={type==='number'?0:undefined} step={type==='number'?'any':undefined} value={String(form[key]??'')} onChange={e=>set(key,type==='number'?Number(e.target.value):e.target.value)} data-testid={`input-plan-${key}`}/></div>)}<div className="form-field full"><label style={{display:'flex',alignItems:'center',gap:8,fontSize:11,color:'#526b7f'}}><input type="checkbox" checked={form.finishNextDay} onChange={e=>set('finishNextDay',e.target.checked)} data-testid="checkbox-finish-next-day"/> Finish occurs on the next calendar day (cross-midnight exception)</label></div></div>{error&&<div className="error-msg" role="alert">{error}</div>}<div className="form-actions"><button type="button" className="button" onClick={()=>{setForm(blankPlan());setError('');}} data-testid="button-clear-plan-form">Clear form</button><button type="button" className="button" onClick={onClose}>Cancel</button><button className="button primary" type="submit" data-testid="button-save-plan"><Check size={14}/> Save plan</button></div></form></div></div>;
}
function ActualPage({data,actualFor,save}:{data:Dataset;actualFor:(id:string)=>Actual|undefined;save:(a:Actual)=>void}){
 const [selected,setSelected]=useState('');const [form,setForm]=useState<Partial<Actual>>({});const [error,setError]=useState('');
 const current=data.plans.find(p=>p.id===selected);const existing=selected?actualFor(selected):undefined;
 useEffect(()=>{if(selected){const a=data.actuals.find(item=>item.planId===selected);setForm(a?{...a}:{planId:selected,volume:undefined,grade:data.plans.find(p=>p.id===selected)?.grade||'',trucks:undefined,requested:'',pumpAtSite:'',dispatch:'',returned:'',status:'Completed',reason:'',remarks:''});setError('');}},[selected,data.plans,data.actuals]);
 const metrics=current?(()=>{const start=delay(form.dispatch||'',current.start);const finish=delay(form.returned||'',current.finish,current.finishNextDay?1440:0);return{start,finish};})():null;
  const submit=(e:FormEvent)=>{e.preventDefault();if(!current)return;if(form.volume==null||!Number.isFinite(form.volume)||form.trucks==null||!Number.isFinite(form.trucks)||!form.dispatch||!form.returned||!form.status){setError('Complete actual volume, trucks, first dispatch, last return and operation status.');return;}if(form.volume<0||form.trucks<0){setError('Actual volume and trucks cannot be negative.');return;}save({id:existing?.id||uid(),planId:current.id,volume:Number(form.volume),grade:String(form.grade||''),trucks:Number(form.trucks),requested:String(form.requested||''),pumpAtSite:String(form.pumpAtSite||''),dispatch:String(form.dispatch),returned:String(form.returned),status:form.status as Status,reason:String(form.reason||''),remarks:String(form.remarks||'')});};
 return <div className="content"><PageHeader eyebrow="Execution capture" title="Delivery actuals" subtitle="Record what happened against a saved daily plan."><span className="notice" style={{padding:'8px 10px'}}>Actual entries save to this browser</span></PageHeader><div className="grid-main" style={{gridTemplateColumns:'minmax(260px,.72fr) minmax(0,1.5fr)'}}><Panel title="Choose scheduled job" subtitle="Select a plan to enter or update execution"><div className="panel-body"><label className="field-label" htmlFor="actual-plan">Plan / project</label><select id="actual-plan" className="field" style={{width:'100%'}} value={selected} onChange={e=>setSelected(e.target.value)} data-testid="select-actual-plan"><option value="">Select a saved plan…</option>{data.plans.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(p=><option value={p.id} key={p.id}>{p.date} · {p.project} · {p.so}</option>)}</select>{current?<div style={{marginTop:20}}><div className="eyebrow">Planned delivery</div><div className="project-cell" style={{fontSize:14}}>{current.project}</div><div className="secondary-cell" style={{marginTop:5}}>{current.location} · {current.grade}</div><div className="metric-line"><span>Planned volume</span><strong>{num(current.volume)} m³</strong></div><div className="metric-line"><span>Allocated fleet</span><strong>{current.trucks} trucks</strong></div><div className="metric-line"><span>Planned timing</span><strong>{current.start} – {current.finish}{current.finishNextDay?' +1d':''}</strong></div></div>:<EmptyText text="Select a plan to see the schedule and enter its actual delivery."/>}</div></Panel>
  <Panel title={existing?'Update operation actual':'Capture operation actual'} subtitle={current?`Actual delivery against ${current.so}`:'Choose a saved plan to enable actual entry'}>{current?<form className="panel-body" onSubmit={submit}><div className="form-grid"><div className="form-section">Delivery output</div><InputField label="Actual volume (m³) *" type="number" min={0} value={form.volume??''} onChange={v=>setForm({...form,volume:v===''?undefined:Number(v)})}/><InputField label="Actual grade" value={form.grade||''} onChange={v=>setForm({...form,grade:v})}/><InputField label="Actual trucks used *" type="number" min={0} value={form.trucks??''} onChange={v=>setForm({...form,trucks:v===''?undefined:Number(v)})}/><div className="form-section">Operation timing</div><InputField label="Requested-by-site time" type="time" value={form.requested||''} onChange={v=>setForm({...form,requested:v})}/><InputField label="Pump car at site" type="time" value={form.pumpAtSite||''} onChange={v=>setForm({...form,pumpAtSite:v})}/><InputField label="First truck dispatched *" type="time" value={form.dispatch||''} onChange={v=>setForm({...form,dispatch:v})}/><InputField label="Last truck returned *" type="time" value={form.returned||''} onChange={v=>setForm({...form,returned:v})}/><div className="form-section">Close-out</div><div className="form-field"><label className="field-label">Operation status *</label><select className="field" value={form.status||'Completed'} onChange={e=>setForm({...form,status:e.target.value as Status})}>{['Completed','Partial','Cancelled','Pending'].map(x=><option key={x}>{x}</option>)}</select></div><div className="form-field"><label className="field-label">Delay reason</label><select className="field" value={form.reason||''} onChange={e=>setForm({...form,reason:e.target.value})}><option value="">Choose reason…</option>{REASONS.map(x=><option key={x}>{x}</option>)}</select></div><div className="form-field full"><label className="field-label">Remarks</label><textarea className="field" rows={2} value={form.remarks||''} onChange={e=>setForm({...form,remarks:e.target.value})} placeholder="Operational context or handover notes"/></div></div>{metrics&&<div style={{marginTop:18}}><div className="eyebrow">Calculated variance · minutes from plan</div><div className="timing-grid"><div className="timing-card"><small>First dispatch vs planned start</small><strong>{metrics.start===null?'—':`${metrics.start>0?'+':''}${metrics.start} min`}</strong><em>{metrics.start===null?'Enter a dispatch time':bandText(metrics.start)}</em></div><div className="timing-card"><small>Last return vs planned finish</small><strong>{metrics.finish===null?'—':`${metrics.finish>0?'+':''}${metrics.finish} min`}</strong><em>{metrics.finish===null?'Enter a return time':bandText(metrics.finish)}</em></div></div></div>}{error&&<div className="error-msg">{error}</div>}<div className="form-actions"><button type="submit" className="button primary" data-testid="button-save-actual"><Check size={14}/> Save operation actual</button></div></form>:<div className="panel-body"><EmptyText text="Actual fields will be ready once a saved daily plan is selected."/></div>}</Panel></div></div>;
}
function InputField({label,type='text',value,onChange,min}:{label:string;type?:string;value:string|number;onChange:(v:string)=>void;min?:number}){return <div className="form-field"><label className="field-label">{label}</label><input className="field" type={type} min={min} step={type==='number'?'any':undefined} value={value} onChange={e=>onChange(e.target.value)}/></div>}

function Comparison({data,actualFor}:{data:Dataset;actualFor:(id:string)=>Actual|undefined}){
  const [q,setQ]=useState('');const [date,setDate]=useState('');const [project,setProject]=useState('');const [delayFilter,setDelayFilter]=useState('all');const [sort,setSort]=useState('newest');
  const rows=rowData(data,actualFor).filter(x=>(!date||x.p.date===date)&&(!project||x.p.project===project)&&`${x.p.project} ${x.p.so} ${x.p.location} ${x.p.grade}`.toLowerCase().includes(q.toLowerCase())&&(delayFilter==='all'||(delayFilter==='delayed'&&x.delayTotal>0)||(delayFilter==='on-time'&&x.a&&x.delayTotal===0)||(delayFilter==='pending'&&!x.a))).sort((a,b)=>sort==='project'?a.p.project.localeCompare(b.p.project):sort==='delay'?b.delayTotal-a.delayTotal:b.p.date.localeCompare(a.p.date));
  return <div className="content"><PageHeader eyebrow="Variance analysis" title="Plan vs actual" subtitle="Find the gap between dispatch intent and delivery reality."/><Panel title="Delivery comparison" subtitle={`${rows.length} jobs in this view`}><div className="filter-bar"><div className="field" style={{display:'flex',gap:7,alignItems:'center',padding:'0 9px'}}><Search size={14} color="#8797a5"/><input className="field search-field" style={{border:0,padding:'8px 0'}} value={q} onChange={e=>setQ(e.target.value)} placeholder="Search project / SO" data-testid="input-comparison-search"/></div><input type="date" className="field" value={date} onChange={e=>setDate(e.target.value)} aria-label="Filter comparison date"/><select className="field" value={project} onChange={e=>setProject(e.target.value)}><option value="">All projects</option>{Array.from(new Set(data.plans.map(p=>p.project))).map(p=><option key={p}>{p}</option>)}</select><select className="field" value={delayFilter} onChange={e=>setDelayFilter(e.target.value)}><option value="all">All execution states</option><option value="delayed">Delayed</option><option value="on-time">On time</option><option value="pending">Awaiting actual</option></select><select className="field" value={sort} onChange={e=>setSort(e.target.value)} aria-label="Sort comparison records"><option value="newest">Newest first</option><option value="project">Project A–Z</option><option value="delay">Highest delay first</option></select><span style={{marginLeft:'auto',fontSize:10,color:'#7d8c99'}}><Filter size={12} style={{verticalAlign:'middle',marginRight:4}}/>Delay minutes stay visible, including early values</span></div><div className="table-wrap"><table><thead><tr><th>SN</th><th>Date</th><th>Customer / project</th><th>Location</th><th>Grade</th><th>Planned volume</th><th>Actual volume</th><th>Volume difference</th><th>Allocated trucks</th><th>Actual trucks</th><th>Truck difference</th><th>Planned start</th><th>Actual first dispatch</th><th>Start difference</th><th>Planned finish</th><th>Actual last return</th><th>Finish difference</th><th>Delay status</th><th>Delay minutes</th><th>Delay reason</th></tr></thead><tbody>{rows.map(({p,a,start,finish,volumeDelta,truckDelta,delayTotal})=><tr key={p.id} data-testid={`row-comparison-${p.id}`}><td className="mono">{p.sn}</td><td className="mono">{p.date}</td><td className="project-cell">{p.project}<div className="secondary-cell">{p.so}</div></td><td>{p.location}</td><td>{p.grade}</td><td className="mono">{num(p.volume)} m³</td><td className="mono">{a?`${num(a.volume)} m³`:'—'}</td><td className="mono">{volumeDelta===null?'—':`${volumeDelta>0?'+':''}${num(volumeDelta)} m³`}</td><td className="mono">{p.trucks}</td><td className="mono">{a?num(a.trucks):'—'}</td><td className="mono">{truckDelta===null?'—':`${truckDelta>0?'+':''}${truckDelta}`}</td><td className="mono">{p.start}</td><td className="mono">{a?.dispatch||'—'}</td><td><DelayValue value={start}/></td><td className="mono">{p.finish}{p.finishNextDay?' +1d':''}</td><td className="mono">{a?.returned||'—'}</td><td><DelayValue value={finish}/></td><td>{a?<span className={`badge ${band(delayTotal)}`}>{bandText(delayTotal)}</span>:<span className="badge pending">Pending</span>}</td><td className="mono">{a?`${delayTotal} min`:'—'}</td><td>{a?.reason||'—'}</td></tr>)}{!rows.length&&<tr><td colSpan={20}><EmptyText text="No plan records match the selected filters."/></td></tr>}</tbody></table></div></Panel></div>;
}

function DelaysPage({data,actualFor}:{data:Dataset;actualFor:(id:string)=>Actual|undefined}){
 const [from,setFrom]=useState('');const [to,setTo]=useState('');const [project,setProject]=useState('');
 const rows=rowData(data,actualFor).filter(x=>x.a&&(!from||x.p.date>=from)&&(!to||x.p.date<=to)&&(!project||x.p.project===project));
 const delays=rows.filter(x=>(x.start||0)>0||(x.finish||0)>0);
 const reasons=REASONS.map(reason=>{const items=rows.filter(x=>x.a?.reason===reason);const minutes=items.reduce((s,x)=>s+Math.max(0,x.start||0)+Math.max(0,x.finish||0),0);return{reason,items,minutes,avg:items.length?Math.round(minutes/items.length):0};}).filter(x=>x.items.length).sort((a,b)=>b.minutes-a.minutes);
  const visiblePlans=data.plans.filter(p=>(!from||p.date>=from)&&(!to||p.date<=to)&&(!project||p.project===project));
  const projects=Array.from(new Set(visiblePlans.map(x=>x.project))).map(name=>{const list=rows.filter(x=>x.p.project===name),plans=visiblePlans.filter(x=>x.project===name),actual=list.reduce((s,x)=>s+(x.a?.volume||0),0),planned=plans.reduce((s,x)=>s+x.volume,0),d=list.reduce((s,x)=>s+x.delayTotal,0);return{name,list,plannedJobs:plans.length,planned,actual,variance:actual-planned,delayed:list.filter(x=>x.delayTotal>0).length,mins:d,avg:list.length?Math.round(d/list.length):0};});
 const timeline=rows.slice().sort((a,b)=>a.p.date.localeCompare(b.p.date)).slice(-14);
  return <div className="content"><PageHeader eyebrow="Root-cause view" title="Delay intelligence" subtitle="Turn lost minutes into clear reasons and project-level opportunities."/><Panel title="Analysis filters" subtitle="Apply a date window and project focus"><div className="filter-bar"><label className="field-label" style={{margin:0}}>From <input className="field" type="date" value={from} onChange={e=>setFrom(e.target.value)} style={{marginLeft:6}}/></label><label className="field-label" style={{margin:0}}>To <input className="field" type="date" value={to} onChange={e=>setTo(e.target.value)} style={{marginLeft:6}}/></label><select className="field" value={project} onChange={e=>setProject(e.target.value)}><option value="">All projects</option>{Array.from(new Set(data.plans.map(p=>p.project))).map(x=><option key={x}>{x}</option>)}</select><span className="plant-chip">{delays.length} delayed of {rows.length} actual jobs</span></div></Panel><div className="grid-equal" style={{marginTop:15}}><Panel title="Delay reason breakdown" subtitle="Occurrence count, total impact and average per job"><div className="table-wrap"><table style={{minWidth:450}}><thead><tr><th>Reason</th><th>Occurrences</th><th>Total delay</th><th>Avg / job</th></tr></thead><tbody>{reasons.map(r=><tr key={r.reason}><td className="project-cell">{r.reason}</td><td className="mono">{r.items.length}</td><td className="mono">{r.minutes} min</td><td className="mono">{r.avg} min</td></tr>)}{!reasons.length&&<tr><td colSpan={4}><EmptyText text="No delay reasons found in this date window."/></td></tr>}</tbody></table></div></Panel><Panel title="Delay trend" subtitle="Per-job positive delay · chronological view"><div className="panel-body">{timeline.length?<div className="bar-chart">{timeline.map((x,i)=><div className="bar-row" key={x.p.id}><span>{x.p.date.slice(5)} · {x.p.project.slice(0,9)}</span><div className="bar-track"><div className="bar-fill-actual" style={{width:`${Math.min(100,x.delayTotal/Math.max(1,...timeline.map(t=>t.delayTotal))*100)}%`}}/></div><span className="bar-number">{x.delayTotal}m</span></div>)}</div>:<EmptyText text="Record operation actuals to reveal delay trends."/>}</div></Panel></div><Panel title="Project performance" subtitle="Delivery completion and time/volume performance by project"><div className="table-wrap"><table><thead><tr><th>Project</th><th>Planned jobs</th><th>Completed jobs</th><th>Delayed jobs</th><th>Avg delay</th><th>Total delay</th><th>Planned volume</th><th>Actual volume</th><th>Volume variance</th></tr></thead><tbody>{projects.map(x=><tr key={x.name}><td className="project-cell">{x.name}</td><td className="mono">{x.plannedJobs}</td><td className="mono">{x.list.filter(y=>y.a?.status==='Completed').length}</td><td className="mono">{x.delayed}</td><td className="mono">{x.avg} min</td><td className="mono">{x.mins} min</td><td className="mono">{x.planned} m³</td><td className="mono">{x.actual} m³</td><td className="mono">{x.variance>0?'+':''}{x.variance} m³</td></tr>)}{!projects.length&&<tr><td colSpan={9}><EmptyText text="No project performance records in this view."/></td></tr>}</tbody></table></div></Panel></div>;
}

function RecordsPage({data,actualFor,updatePlan,removePlan,saveNow,clear}:{data:Dataset;actualFor:(id:string)=>Actual|undefined;updatePlan:(p:Plan)=>void;removePlan:(id:string)=>void;saveNow:()=>void;clear:()=>void}){
 const [q,setQ]=useState('');const [from,setFrom]=useState('');const [to,setTo]=useState('');const [state,setState]=useState('all');const [sort,setSort]=useState('newest');const [editing,setEditing]=useState<Plan|null>(null);const restoreRef=useRef<HTMLInputElement>(null);const importRef=useRef<HTMLInputElement>(null);
 const rows=rowData(data,actualFor).filter(x=>(!from||x.p.date>=from)&&(!to||x.p.date<=to)&&`${x.p.project} ${x.p.so} ${x.p.location} ${x.p.grade}`.toLowerCase().includes(q.toLowerCase())&&(state==='all'||(state==='pending'&&!x.a)||(state==='delayed'&&x.a&&x.delayTotal>0)||(state==='on-time'&&x.a&&x.delayTotal===0))).sort((a,b)=>sort==='oldest'?a.p.date.localeCompare(b.p.date):b.p.date.localeCompare(a.p.date));
 const download=(name:string,text:string,type:string)=>{const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);};
 const csvEscape=(x:unknown)=>`"${String(x??'').replaceAll('"','""')}"`;
 const exportPlans=()=>download('peliyagoda-daily-plans.csv',[['SN','Plan date','Customer / project','Location','Grade','SO number','Planned volume m3','Pump car','Allocated trucks','Pump car at site','Planned start','Planned finish','Requested by site','1st dispatch','Last return','Ice per m3','Total ice','Mix design','SAP BOM','PO reference','Lab helper'].map(csvEscape).join(','),...data.plans.map(p=>[p.sn,p.date,p.project,p.location,p.grade,p.so,p.volume,p.pumpCar,p.trucks,p.pumpAtSite,p.start,p.finish,p.requested,p.dispatch,p.returned,p.icePerM3,p.totalIce,p.mix,p.sap,p.po,p.labHelper].map(csvEscape).join(','))].join('\n'),'text/csv');
 const exportComparison=()=>download('peliyagoda-plan-vs-actual.csv',[['Plan date','Project','SO number','Plan volume','Actual volume','Volume delta','Allocated trucks','Actual trucks','Truck delta','Planned start','Actual dispatch','Start delay minutes','Planned finish','Actual return','Finish delay minutes','Status','Delay reason','Remarks'].map(csvEscape).join(','),...rows.map(({p,a,start,finish,volumeDelta,truckDelta})=>[p.date,p.project,p.so,p.volume,a?.volume,volumeDelta,p.trucks,a?.trucks,truckDelta,p.start,a?.dispatch,start,p.finish,a?.returned,finish,a?.status,a?.reason,a?.remarks].map(csvEscape).join(','))].join('\n'),'text/csv');
 const backup=()=>download('peliyagoda-operations-backup.json',JSON.stringify({...data,backupCreatedAt:new Date().toISOString()},null,2),'application/json');
 const restore=(file:File|null)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(String(reader.result));if(!Array.isArray(parsed.plans)||!Array.isArray(parsed.actuals))throw new Error('Invalid backup format');if(window.confirm(`Restore ${parsed.plans.length} plans and ${parsed.actuals.length} actuals? This replaces current browser records.`)){localStorage.setItem(STORAGE,JSON.stringify(parsed));window.location.reload();}}catch{window.alert('This JSON file is not a valid Peliyagoda operations backup.');}};reader.readAsText(file);};
 const importCsv=(file:File|null)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const lines=String(reader.result).trim().split(/\r?\n/);if(lines.length<2)throw new Error();const split=(line:string)=>line.match(/("([^"]|"")*"|[^,]*)(,|$)/g)?.map(v=>v.replace(/,$/,'').replace(/^"|"$/g,'').replaceAll('""','"'))||[];const headers=split(lines[0]).map(x=>x.toLowerCase().trim());const idx=(...names:string[])=>headers.findIndex(h=>names.includes(h));const imported=lines.slice(1).map((line,i)=>{const c=split(line);const get=(...names:string[])=>{const n=idx(...names);return n>=0?c[n]||'':''};const volume=Number(get('planned volume m3','planned volume (m³)','planned volume','volume'));const p:Plan={...blankPlan(),id:uid(),sn:Math.max(0,...data.plans.map(x=>x.sn))+i+1,date:get('plan date','date')||today(),project:get('customer / project','customer/project','project'),location:get('location'),grade:get('grade','concrete grade'),so:get('so number','so no.','so'),volume:Number.isFinite(volume)?volume:0,pumpCar:get('pump car','pump car number'),trucks:Number(get('allocated trucks','trucks'))||0,start:get('planned start','start'),finish:get('planned finish','finish'),requested:get('requested by site','requested-by-site time'),dispatch:get('1st dispatch','1st-truck-dispatched time'),returned:get('last return','last-truck-returned time'),icePerM3:Number(get('ice per m3'))||0,totalIce:Number(get('total ice'))||0,mix:get('mix design','mix design/admixture'),sap:get('sap bom','sap bom code'),po:get('po reference','po'),labHelper:get('lab helper','lab helper name')};if(!p.project||!p.location||!p.grade||!p.so||!p.start||!p.finish||p.volume<0)throw new Error('Required columns missing or invalid');return p;});persistImport(imported);}catch{window.alert('Import failed. Use the Plans CSV export as the template and include required columns.');}};const persistImport=(items:Plan[])=>{if(items.length)setDataAfterImport(items);};const setDataAfterImport=(items:Plan[])=>{localStorage.setItem(STORAGE,JSON.stringify({plans:[...items,...data.plans],actuals:data.actuals}));window.location.reload();};reader.readAsText(file);};
  return <div className="content"><PageHeader eyebrow="Local archive" title="Operations records" subtitle="Search, compare, edit and export the full plan and execution history."/><div className="grid-equal" style={{marginBottom:15}}><Panel title="Data controls" subtitle="Persisted in this browser only"><div className="panel-body"><div className="data-controls"><button className="button primary" onClick={saveNow} data-testid="button-save-data"><Check size={14}/> Save data</button><button className="button" onClick={exportPlans} data-testid="button-export-plans"><Download size={14}/> Plans CSV</button><button className="button" onClick={exportComparison} data-testid="button-export-comparison"><FileSpreadsheet size={14}/> Plan vs actual CSV</button><button className="button" onClick={backup} data-testid="button-backup-json"><FileJson2 size={14}/> JSON backup</button><button className="button" onClick={()=>importRef.current?.click()} data-testid="button-import-csv"><Upload size={14}/> Import plans CSV</button><button className="button" onClick={()=>restoreRef.current?.click()} data-testid="button-restore-json"><Upload size={14}/> Restore JSON</button><button className="button danger" onClick={clear} data-testid="button-clear-data"><Trash2 size={14}/> Clear all data</button><input ref={importRef} className="file-input" type="file" accept=".csv,text/csv" onChange={e=>importCsv(e.target.files?.[0]||null)}/><input ref={restoreRef} className="file-input" type="file" accept=".json,application/json" onChange={e=>restore(e.target.files?.[0]||null)}/></div><div className="notice" style={{marginTop:14}}><LockKeyhole size={13} style={{verticalAlign:'middle',marginRight:6}}/>Storage adapter is isolated in the frontend. Replace browser localStorage with a secured server-side store and access controls before production use.</div></div></Panel><Panel title="Archive at a glance" subtitle="Current local records"><div className="panel-body split-stat"><div className="small-stat"><span>Daily plans</span><strong>{data.plans.length}</strong></div><div className="small-stat"><span>Actuals captured</span><strong>{data.actuals.length}</strong></div><div className="small-stat"><span>Awaiting actuals</span><strong>{data.plans.filter(p=>!actualFor(p.id)).length}</strong></div><div className="small-stat"><span>Projects</span><strong>{new Set(data.plans.map(x=>x.project)).size}</strong></div></div></Panel></div>
 <Panel title="All saved operations" subtitle={`${rows.length} of ${data.plans.length} plans shown`}><div className="filter-bar"><div className="field" style={{display:'flex',alignItems:'center',gap:8,padding:'0 9px'}}><Search size={14} color="#8797a5"/><input className="field search-field" style={{border:0,padding:'8px 0'}} placeholder="Project, location, SO or grade" value={q} onChange={e=>setQ(e.target.value)} data-testid="input-record-search"/></div><input type="date" className="field" value={from} onChange={e=>setFrom(e.target.value)} aria-label="Records from date"/><input type="date" className="field" value={to} onChange={e=>setTo(e.target.value)} aria-label="Records to date"/><select className="field" value={state} onChange={e=>setState(e.target.value)}><option value="all">All statuses</option><option value="pending">Awaiting actual</option><option value="delayed">Delayed</option><option value="on-time">On time</option></select><select className="field" value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></div><div className="table-wrap"><table><thead><tr><th>Date / project</th><th>SO / grade</th><th>Plan volume</th><th>Actual volume</th><th>Start / finish delay</th><th>Reason</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows.map(({p,a,start,finish})=><tr key={p.id}><td><span className="mono">{p.date}</span><div className="project-cell" style={{marginTop:4}}>{p.project}</div><div className="secondary-cell">{p.location}</div></td><td>{p.so}<div className="secondary-cell">{p.grade}</div></td><td className="mono">{p.volume} m³</td><td className="mono">{a?`${a.volume} m³`:'—'}</td><td><div><DelayValue value={start}/></div><div style={{marginTop:4}}><DelayValue value={finish}/></div></td><td>{a?.reason||'—'}</td><td><StatusBadge status={a?.status||'Pending'} delayMin={start}/></td><td><div className="actions"><button className="button small" onClick={()=>setEditing(p)} title="Edit plan"><Pencil size={12}/> Edit plan</button><button className="button small danger" onClick={()=>window.confirm(`Remove ${p.project} and linked actual?`)&&removePlan(p.id)} title="Delete record"><Trash2 size={12}/></button></div></td></tr>)}{!rows.length&&<tr><td colSpan={8}><EmptyText text="No saved records match your search or filters."/></td></tr>}</tbody></table></div></Panel>{editing&&<PlanModal initial={editing} onClose={()=>setEditing(null)} onSave={p=>{updatePlan({...p,id:editing.id,sn:editing.sn});setEditing(null);}}/>}<p className="footer-note"></p></div>;
}

function App(){return <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><OperationsApp/></WouterRouter>;}

export default App;